describe('RBAC deny-by-default', () => {
  it.each(['event.fly', 'task.nuke', 'rbac.self_grant', '', 'admin.*'])(
    'unknown action %s => 403', async (a) => {
      await expect(authorize({ role: 'admin' }, a, { impactClass: 'S0' })).rejects.toMatchObject({ statusCode: 403 });
    });
});

describe('reportApplyRule (QA C2)', () => {
  const cases = [
  {
    "name": "own task, S0, unlocked",
    "impactClass": "S0",
    "locked": false,
    "own": true,
    "expected": "auto-apply"
  },
  {
    "name": "own task, S0, LOCKED",
    "impactClass": "S0",
    "locked": true,
    "own": true,
    "expected": "pending_review"
  },
  {
    "name": "own task, S1",
    "impactClass": "S1",
    "locked": false,
    "own": true,
    "expected": "pending_review"
  },
  {
    "name": "other's task, S0",
    "impactClass": "S0",
    "locked": false,
    "own": false,
    "expected": "deny"
  }
];
  for (const c of cases) {
    it(`delay report: ${c.name} => ${c.expected}`, async () => {
      const d = await reportDecision({ role: 'focus_worker' }, c);
      expect(d).toBe(c.expected);
    });
  }
});

